import {query,saveConfig} from '../client.js';
const usage={
  org:`Organization administration
  crew org list [--limit N --cursor CURSOR]
  crew org show ID
  crew org create --name NAME
  crew org rename ID --name NAME
  crew org members ID [--limit N --cursor CURSOR]
  crew org add ID --user USER_ID [--role member]
  crew org role ID --user USER_ID --role ROLE
  crew org remove ID --user USER_ID --yes
  crew org audit ID [--actor ID --entity-type TYPE --entity ID --action ACTION --from ISO --to ISO]
  crew org guests PROJECT_ID
  crew org grant PROJECT_ID --user USER_ID
  crew org ungrant PROJECT_ID --user USER_ID --yes`,
  team:`Team administration
  crew team list --org ID [--limit N --cursor CURSOR]
  crew team show ID
  crew team create --org ID --name NAME [--description TEXT]
  crew team update ID --name NAME [--description TEXT]
  crew team delete ID --yes
  crew team members ID [--limit N --cursor CURSOR]
  crew team add ID --user USER_ID
  crew team remove ID --user USER_ID --yes`,
  invite:`One-use invitations
  crew invite list --org ID [--state pending|accepted|expired|revoked|all]
  crew invite create --org ID --email EMAIL [--role member --hours 168 --projects ID,ID]
  crew invite preview --link URL
  crew invite accept --link URL
  crew invite revoke ID --yes
  crew invite outbox [--org ID] [--limit N --cursor CURSOR]
  Accept requires the account with the invited email. Use --credential TOKEN instead of --link if needed.`,
  token:`Personal API tokens
  crew token list [--state active|expired|revoked|all --limit N --cursor CURSOR]
  crew token create --name NAME [--scopes self:read,org:read,project:read --days N --save-to FILE]
  crew token revoke ID --yes
  Token creation displays its secret exactly once, or writes restricted credentials to --save-to.
  Scope grants never expand organization roles or project access.`
};
function required(value,label) {
  if(typeof value!=='string'||!value.trim())throw new Error('Missing '+label);
  return value;
}
function id(args) {return encodeURIComponent(required(args[1],'resource id'));}
function option(ctx,name) {return required(ctx.options[name],'--'+name);}
function confirm(ctx,action) {if(ctx.options.yes!==true)throw new Error(action+' requires --yes');}
function page(options,extra={}) {return query({limit:options.limit,cursor:options.cursor,...extra});}
function credential(options) {
  if(options.credential&&options.link)throw new Error('Choose either --link or --credential');
  if(options.credential)return options.credential;
  const link=required(options.link,'--link URL or --credential TOKEN');
  let parsed;
  try{const url=new URL(link);parsed=new URLSearchParams(url.hash.split('?')[1]??url.search.slice(1)).get('token');}
  catch{throw new Error('Invalid invitation URL');}
  return required(parsed,'token in invitation URL');
}
function help(ctx,group) {if(ctx.options.help||ctx.args[0]==='help'||!ctx.args.length){ctx.print(usage[group]);return true;}return false;}
async function organization(ctx) {
  if(help(ctx,'org'))return;
  const {args,options,client,print}=ctx;
  const action=args[0];
  if(action==='list')return print(await client.get('/orgs'+page(options)));
  if(action==='create')return print(await client.post('/orgs',{name:option(ctx,'name')}));
  const target=id(args),base='/orgs/'+target;
  if(action==='show')return print(await client.get(base));
  if(action==='rename')return print(await client.patch(base,{name:option(ctx,'name')}));
  if(action==='members')return print(await client.get(base+'/members'+page(options)));
  if(action==='add')return print(await client.post(base+'/members',{userId:option(ctx,'user'),role:options.role??'member'}));
  if(action==='role')return print(await client.patch(base+'/members/'+encodeURIComponent(option(ctx,'user')),{role:option(ctx,'role')}));
  if(action==='remove'){confirm(ctx,'Member removal');return print(await client.delete(base+'/members/'+encodeURIComponent(option(ctx,'user'))));}
  if(action==='audit')return print(await client.get(base+'/audit'+page(options,{actorId:options.actor,entityType:options['entity-type'],entityId:options.entity,action:options.action,projectId:options.project,from:options.from,to:options.to})));
  const project='/projects/'+target+'/guests';
  if(action==='guests')return print(await client.get(project+page(options)));
  if(action==='grant')return print(await client.post(project,{userId:option(ctx,'user')}));
  if(action==='ungrant'){confirm(ctx,'Project grant removal');return print(await client.delete(project+'/'+encodeURIComponent(option(ctx,'user'))));}
  throw new Error('Unknown org action: '+action+'; use crew org --help');
}
async function team(ctx) {
  if(help(ctx,'team'))return;
  const {args,options,client,print}=ctx;
  const action=args[0];
  if(action==='list')return print(await client.get('/orgs/'+encodeURIComponent(option(ctx,'org'))+'/teams'+page(options)));
  if(action==='create')return print(await client.post('/orgs/'+encodeURIComponent(option(ctx,'org'))+'/teams',{name:option(ctx,'name'),description:options.description??''}));
  const target=id(args),base='/teams/'+target;
  if(action==='show')return print(await client.get(base));
  if(action==='update') {
    const current=(await client.get(base)).team;
    if(options.name===undefined&&options.description===undefined)throw new Error('Provide --name or --description');
    return print(await client.patch(base,{name:options.name??current.name,description:options.description??current.description}));
  }
  if(action==='delete'){confirm(ctx,'Team deletion');return print(await client.delete(base));}
  if(action==='members')return print(await client.get(base+'/members'+page(options)));
  if(action==='add')return print(await client.post(base+'/members',{userId:option(ctx,'user')}));
  if(action==='remove'){confirm(ctx,'Team member removal');return print(await client.delete(base+'/members/'+encodeURIComponent(option(ctx,'user'))));}
  throw new Error('Unknown team action: '+action+'; use crew team --help');
}
async function invitation(ctx) {
  if(help(ctx,'invite'))return;
  const {args,options,client,print}=ctx;
  const action=args[0];
  if(action==='list')return print(await client.get('/orgs/'+encodeURIComponent(option(ctx,'org'))+'/invitations'+page(options,{state:options.state})));
  if(action==='create') {
    const body={email:option(ctx,'email'),role:options.role??'member'};
    if(options.hours!==undefined)body.expiresInHours=Number(options.hours);
    if(options.projects!==undefined)body.projectIds=options.projects.split(',').map(id=>id.trim()).filter(Boolean);
    return print(await client.post('/orgs/'+encodeURIComponent(option(ctx,'org'))+'/invitations',body));
  }
  if(action==='preview')return print(await client.post('/invitations/preview',{token:credential(options)}));
  if(action==='accept')return print(await client.post('/invitations/accept',{token:credential(options)}));
  if(action==='revoke'){confirm(ctx,'Invitation revocation');return print(await client.delete('/invitations/'+id(args)));}
  if(action==='outbox')return print(await client.get((options.org?'/orgs/'+encodeURIComponent(options.org)+'/outbox':'/me/outbox')+page(options)));
  throw new Error('Unknown invite action: '+action+'; use crew invite --help');
}
async function token(ctx) {
  if(help(ctx,'token'))return;
  const {args,options,client,print}=ctx;
  const action=args[0];
  if(action==='list')return print(await client.get('/tokens'+page(options,{state:options.state})));
  if(action==='create') {
    const body={name:option(ctx,'name')};
    if(options.scopes!==undefined)body.scopes=options.scopes.split(',').map(scope=>scope.trim()).filter(Boolean);
    if(options.days!==undefined)body.expiresInDays=Number(options.days);
    const result=await client.post('/tokens',body);
    if(options['save-to']) {
      await saveConfig({url:client.url,token:result.token},options['save-to']);
      return print({personalToken:result.personalToken,savedTo:options['save-to']});
    }
    return print(result);
  }
  if(action==='revoke'){confirm(ctx,'Token revocation');return print(await client.delete('/tokens/'+id(args)));}
  throw new Error('Unknown token action: '+action+'; use crew token --help');
}
export const commands={org:organization,team,invite:invitation,token};
for(const [name,handler] of Object.entries(commands))handler.help=usage[name];

import {existsSync} from 'node:fs';
import {CrewClient,readConfig,configPath} from './client.js';
import {format} from './output.js';
import {commands as auth} from './commands/auth.js';
export function parseArgs(argv) {
  const positional=[];const options={};
  const booleans=new Set(['json','help','yes','unread','all']);
  for(let i=0;i<argv.length;i++){
    const arg=argv[i];
    if(arg==='--'){positional.push(...argv.slice(i+1));break;}
    if(!arg.startsWith('--')){positional.push(arg);continue;}
    const [name,...rest]=arg.slice(2).split('=');
    if(!name)throw new Error('Invalid option');
    if(rest.length)options[name]=rest.join('=');
    else if(booleans.has(name))options[name]=true;
    else if(argv[i+1]!==undefined&&!argv[i+1].startsWith('--'))options[name]=argv[++i];
    else throw new Error('Missing value for --'+name);
  }
  return {command:positional[0],args:positional.slice(1),options};
}
export async function runCli(argv,io={write:text=>console.log(text)}) {
  const parsed=parseArgs(argv);
  const commands={...auth};
  for(const lane of ['people','work','insight']){
    const url=new URL(`./commands/${lane}.js`,import.meta.url);
    if(existsSync(url))Object.assign(commands,(await import(url)).commands);
  }
  if(!parsed.command||(parsed.options.help&&!commands[parsed.command]?.help)){io.write('Crew team tracker\nUsage: crew <command> [action] [--url URL] [--token TOKEN] [--json]\nCommands: '+Object.keys(commands).sort().join(', '));return;}
  const command=commands[parsed.command];
  if(!command)throw new Error('Unknown command: '+parsed.command);
  if(parsed.options.help){io.write(command.help);return;}
  const file=parsed.options.config??configPath();
  const config=await readConfig(file);
  const client=new CrewClient({...config,url:parsed.options.url??process.env.CREW_URL??config.url,token:parsed.options.token??process.env.CREW_TOKEN??config.token});
  await command({...parsed,client,configFile:file,print:value=>io.write(format(value,Boolean(parsed.options.json)))});
}

import {AppError,choice,date,text} from '@crew/shared';
const securityTypes=['user','session','api_token','invitation','organization','team'];
const safeFields=new Set(['id','orgId','projectId','userId','name','email','role','projectIds','scopes',
  'createdBy','createdAt','updatedAt','expiresAt','acceptedAt','acceptedBy','revokedAt','state',
  'current','count','otherSessionsRevoked','allSessionsRevoked','apiTokensRevoked']);
export function sanitizeAudit(value) {
  if(value===null||value===undefined)return null;
  if(typeof value!=='object'||Array.isArray(value))return null;
  const output={};
  for(const [key,item] of Object.entries(value)) {
    if(!safeFields.has(key))continue;
    if(['projectIds','scopes'].includes(key)) {
      if(Array.isArray(item))output[key]=item.filter(x=>typeof x==='string').slice(0,200).map(x=>x.slice(0,150));
    }else if(item===null||typeof item==='boolean'||typeof item==='number')output[key]=item;
    else if(typeof item==='string')output[key]=item.slice(0,500);
  }
  return output;
}
export const publicAudit=row=>({id:row.id,actorId:row.actor_id,orgId:row.org_id,projectId:row.project_id,
  entityType:row.entity_type,entityId:row.entity_id,action:row.action,
  before:row.before_json?JSON.parse(row.before_json):null,after:row.after_json?JSON.parse(row.after_json):null,time:row.time});
export function auditFilters(query) {
  const filters={};
  if(query.actorId)filters.actorId=text(query.actorId,'actorId',{max:150});
  if(query.entityId)filters.entityId=text(query.entityId,'entityId',{max:150});
  if(query.projectId)filters.projectId=text(query.projectId,'projectId',{max:150});
  if(query.entityType)filters.entityType=choice(query.entityType,'entityType',[...securityTypes,'project']);
  if(query.action)filters.action=text(query.action,'action',{max:100});
  if(query.from)filters.from=date(query.from,'from');
  if(query.to)filters.to=date(query.to,'to');
  if(filters.from&&filters.to&&filters.from>filters.to)throw new AppError('VALIDATION','From must not be after To',422,{from:'Choose a date before To'});
  return filters;
}
export function registerAudit(ctx) {
  const {db,app,requireAuth,permissions:p}=ctx;
  const insert=db.prepare('INSERT INTO security_audit VALUES (?,?,?,?,?,?,?,?,?,?)');
  const release=ctx.bus.subscribe(event=>{
    const selected=securityTypes.includes(event.entityType)||(event.entityType==='project'&&['guest_added','guest_removed'].includes(event.action));
    if(!selected)return;
    const before=sanitizeAudit(event.before),after=sanitizeAudit(event.after);
    insert.run(event.id,event.actorId??null,event.orgId??null,event.projectId??null,event.entityType,event.entityId,event.action,
      before===null?null:JSON.stringify(before),after===null?null:JSON.stringify(after),event.time);
  });
  (ctx.cleanups??=[]).push(release);
  function list(req,where,values) {
    const filters=auditFilters(req.query);
    const names={actorId:'actor_id',entityId:'entity_id',projectId:'project_id',entityType:'entity_type',action:'action'};
    for(const [key,value] of Object.entries(filters)) {
      where.push(key==='from'?'time>=?':key==='to'?'time<=?':names[key]+'=?');values.push(value);
    }
    const rows=db.prepare('SELECT * FROM security_audit WHERE '+where.join(' AND ')+' ORDER BY time DESC,id').all(...values);
    return ctx.paginate(rows.map(publicAudit),req.query);
  }
  app.get('/api/v1/orgs/:orgId/audit',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'audit:read');
    if(req.query.projectId){const project=p.assertProject(req,req.query.projectId,'project:read');if(project.org_id!==req.params.orgId)return res.status(422).json({error:{code:'VALIDATION',message:'Project belongs to another organization',details:{projectId:'Choose a project in this organization'}}});}
    res.json(list(req,['org_id=?'],[req.params.orgId]));
  });
  app.get('/api/v1/me/audit',requireAuth,(req,res)=>{
    p.assertSelf(req);res.json(list(req,['org_id IS NULL','(actor_id=? OR entity_id=?)'],[req.user.id,req.user.id]));
  });
}

import {AppError,choice} from '@crew/shared';
import {publicOutbox} from './outbox.js';
export function registerOutbox(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/me/outbox',requireAuth,(req,res)=>{
    p.assertSelf(req);
    if(req.auth.kind!=='session')throw new AppError('FORBIDDEN','Use a browser session to view private delivery links',403);
    const kind=req.query.kind?choice(req.query.kind,'kind',['invite','reset','digest']):null;
    const rows=db.prepare('SELECT * FROM outbox WHERE to_email=? AND (user_id IS NULL OR user_id=?) ORDER BY created_at DESC,id').all(req.user.email,req.user.id);
    res.json(ctx.paginate(rows.filter(row=>!kind||row.kind===kind).map(publicOutbox),req.query));
  });
  app.get('/api/v1/orgs/:orgId/outbox',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'invites:manage');
    const rows=db.prepare("SELECT * FROM outbox WHERE org_id=? AND kind='invite' ORDER BY created_at DESC,id").all(req.params.orgId);
    res.json(ctx.paginate(rows.map(publicOutbox),req.query));
  });
}
